  /// Fire an edge flash. `d > 0` = rightward (`›`, next), `d < 0` = leftward
  /// (`‹`, previous); `d == 0` is ignored.
  void flash(int d) {
    if (d == 0) return;
    dir = d;
    _seq++;
    notifyListeners();
  }
}

