  _TapRingPainter({
    required this.center,
    required this.progress,
    required this.color,
  });

  final Offset center;
  final double progress;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    // Expand 0 → ringMaxDiameter/2 while fading 1 → 0. B-030: stroke 3 dp +
